CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY);
CREATE TABLE users(id text PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, verified boolean NOT NULL DEFAULT false, role text NOT NULL DEFAULT 'user' CHECK(role IN ('user','moderator')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profiles(user_id text PRIMARY KEY REFERENCES users ON DELETE CASCADE, display_name text NOT NULL CHECK(length(display_name) BETWEEN 1 AND 64), presence_visible boolean NOT NULL DEFAULT false);
CREATE TABLE verification_tokens(hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE password_reset_tokens(hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE sessions(id text PRIMARY KEY, hash text UNIQUE NOT NULL, user_id text NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE TABLE friend_requests(id text PRIMARY KEY, sender text NOT NULL REFERENCES users ON DELETE CASCADE, recipient text NOT NULL REFERENCES users ON DELETE CASCADE, UNIQUE(sender,recipient), CHECK(sender<>recipient));
CREATE INDEX requests_recipient_idx ON friend_requests(recipient);
CREATE TABLE friendships(a text REFERENCES users ON DELETE CASCADE,b text REFERENCES users ON DELETE CASCADE,PRIMARY KEY(a,b),CHECK(a<b));
CREATE INDEX friendships_b_idx ON friendships(b);
CREATE TABLE blocks(actor text REFERENCES users ON DELETE CASCADE,target text REFERENCES users ON DELETE CASCADE,PRIMARY KEY(actor,target),CHECK(actor<>target));
CREATE INDEX blocks_target_idx ON blocks(target);
CREATE TABLE conversations(id text PRIMARY KEY,pair_key text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversation_members(conversation_id text REFERENCES conversations ON DELETE CASCADE,user_id text REFERENCES users ON DELETE CASCADE,PRIMARY KEY(conversation_id,user_id));
CREATE INDEX conversation_user_idx ON conversation_members(user_id);
CREATE TABLE messages(id text PRIMARY KEY,conversation_id text NOT NULL REFERENCES conversations ON DELETE CASCADE,sender text REFERENCES users ON DELETE SET NULL,body text NOT NULL CHECK(octet_length(body)<=2048),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX messages_conversation_idx ON messages(conversation_id,created_at,id);
CREATE TABLE lobbies(id text PRIMARY KEY,owner text NOT NULL REFERENCES users ON DELETE CASCADE,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 64),capacity integer NOT NULL CHECK(capacity BETWEEN 2 AND 8),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lobby_members(lobby_id text REFERENCES lobbies ON DELETE CASCADE,user_id text REFERENCES users ON DELETE CASCADE,PRIMARY KEY(lobby_id,user_id));
CREATE INDEX lobby_user_idx ON lobby_members(user_id);
CREATE TABLE saves(user_id text REFERENCES users ON DELETE CASCADE,app_id text NOT NULL CHECK(app_id='hypeconnect-demo'),slot text NOT NULL CHECK(slot~'^[a-zA-Z0-9_-]{1,32}$'),revision integer NOT NULL CHECK(revision>0),content text NOT NULL CHECK(octet_length(content)<=1048576),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,app_id,slot));
CREATE TABLE catalog_items(id text PRIMARY KEY,name text NOT NULL,version text NOT NULL,source_url text NOT NULL,license text NOT NULL,sha256 text,rights_status text NOT NULL CHECK(rights_status IN ('pending','approved','withdrawn')),evidence_id text);
CREATE TABLE reports(id text PRIMARY KEY,reporter text REFERENCES users ON DELETE SET NULL,target text REFERENCES users ON DELETE SET NULL,reason text NOT NULL CHECK(length(reason)<=1000),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moderation_actions(id text PRIMARY KEY,moderator text REFERENCES users ON DELETE SET NULL,report_id text REFERENCES reports ON DELETE CASCADE,action text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id text PRIMARY KEY,code text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
